CREATE TABLE rule_regulatory_mechanic(rule_id bigint PRIMARY KEY REFERENCES rule_rule(rule_id),law_level_sets_difficulty boolean NOT NULL CHECK(law_level_sets_difficulty),illegal_ship_inspection_modifier smallint NOT NULL CHECK(illegal_ship_inspection_modifier=-2),bribery_alternative_allowed boolean NOT NULL CHECK(bribery_alternative_allowed));
CREATE TABLE rule_regulatory_operation(rule_id bigint NOT NULL REFERENCES rule_regulatory_mechanic(rule_id),operation_code text NOT NULL CHECK(operation_code IN('avoid-police-harassment','expedite-license','secure-application-approval','avoid-close-paper-inspection','deal-with-bureaucrat','pass-ship-inspection')),display_order smallint NOT NULL CHECK(display_order>0),PRIMARY KEY(rule_id,operation_code),UNIQUE(rule_id,display_order));
CREATE TABLE rule_regulatory_operation_skill(rule_id bigint NOT NULL,operation_code text NOT NULL,skill_rule_id bigint NOT NULL REFERENCES rule_skill(rule_id),PRIMARY KEY(rule_id,operation_code,skill_rule_id),FOREIGN KEY(rule_id,operation_code) REFERENCES rule_regulatory_operation(rule_id,operation_code));
COMMENT ON TABLE rule_regulatory_mechanic IS 'CE-SKILL-014 paired-source Admin and Advocate regulatory mechanics.';
